// A class demonstrating the overload resolution difference
class Widget {
public:
  Widget(int i, bool b) {};         // Constructor 1: int and bool
  Widget(std::initializer_list<long double> il) {}; // Constructor 2: initializer_list
};

Widget w1(10, true);   // Calls Constructor 1 (int, bool)
Widget w2{10, true};   // Calls Constructor 2 (initializer_list)
                       // 10 and true are converted to long double

// The std::vector example
std::vector<int> v1 (10, 20); // Creates a 10-element vector, all elements are 20
std::vector<int> v2 {10, 20}; // Creates a 2-element vector with values 10 and 20
